const METRIC25={world:{population:['인구','population'],food:['식량','food'],wood:['목재','wood'],stone:['석재','stone'],gold:['Gold','totalGold'],territory:['영토 타일','territoryTiles'],health:['평균 건강','avgHealth'],hunger:['평균 Hunger','avgHunger'],happiness:['평균 행복','avgHappiness'],avg_tech:['국가 평균 기술 수','avgTechnologyCount'],knowledge:['누적 Knowledge','totalKnowledge'],price_food:['평균 식량 가격','price_food'],price_wood:['평균 목재 가격','price_wood'],price_stone:['평균 석재 가격','price_stone']},nation:{population:['인구','population'],food:['식량','food'],wood:['목재','wood'],stone:['석재','stone'],gold:['Gold','gold'],territory:['영토 타일','territoryTiles'],health:['평균 건강','avgHealth'],hunger:['평균 Hunger','avgHunger'],happiness:['평균 행복','avgHappiness'],tech:['기술 수','technologyCount'],knowledge:['누적 Knowledge','totalKnowledge'],maintenance_gap:['유지보수 부족률','maintenanceShortfallShare25'],price_food:['평균 식량 가격','price_food'],price_wood:['평균 목재 가격','price_wood'],price_stone:['평균 석재 가격','price_stone']},settlement:{population:['인구','n'],hunger:['평균 Hunger','h'],food:['식량 비축','f'],wood:['목재 비축','w'],stone:['석재 비축','s'],condition:['건물 평균 상태','c'],price_food:['식량 가격','pf'],price_wood:['목재 가격','pw'],price_stone:['석재 가격','ps'],build_used:['사용 건축공간','bu'],build_current:['현재 건축공간','bc'],build_potential:['잠재 건축공간','bp']}};
function statsRows25(ui){const scope=ui.statsScope||'nation',metric=ui.statsMetric||'population',period=Number(ui.statsPeriod||0),now=ui.world.year,key=METRIC25[scope]?.[metric]?.[1];let rows=[];if(scope==='world')rows=(ui.world.telemetry.yearlySummaries||[]).map(x=>({year:x.year,value:x.global?.[key]}));else if(scope==='nation'){const id=Number(ui.statsNationId??ui.world.selectedVillageId);rows=(ui.world.telemetry.yearlySummaries||[]).map(x=>({year:x.year,value:(x.nations||[]).find(n=>n.id===id)?.[key]}));}else{const id=Number(ui.statsNationId??ui.world.selectedVillageId),tile=Number(ui.statsSettlementId??ui.world.selectedTileId);rows=(ui.world.telemetry.settlementYearly?.[`${id}:${tile}`]||[]).map(x=>({year:x.y,value:x[key]}));}rows=rows.filter(r=>Number.isFinite(Number(r.value))).map(r=>({year:Number(r.year),value:Number(r.value)}));if(period>0)rows=rows.filter(r=>r.year>=Math.max(1,now-period+1));return rows;}
function setOptions25(el,sig,html){if(!el)return;if(el.dataset.v25Sig!==sig){const old=el.value;el.innerHTML=html;el.dataset.v25Sig=sig;if([...el.options].some(o=>o.value===old))el.value=old;}}
function renderStats25(ui){const scope=ui.q('statsScope'),nation=ui.q('statsNation'),settle=ui.q('statsSettlement'),metric=ui.q('statsMetric'),period=ui.q('statsPeriod'),canvas=ui.q('statsCanvas');if(!scope||!canvas)return;ui.statsScope=ui.statsScope||'nation';ui.statsNationId=ui.statsNationId??ui.world.selectedVillageId;scope.value=ui.statsScope;setOptions25(nation,ui.world.villages.map(v=>v.id+v.name).join('|'),ui.world.villages.map(v=>`<option value="${v.id}">${v.name}</option>`).join(''));nation.value=String(ui.statsNationId);const v=ui.world.villages.find(x=>x.id===Number(ui.statsNationId))||ui.world.selectedNation,ids=v?[...v.territory]:[];setOptions25(settle,`${v?.id}:${ids.join(',')}`,ids.map(id=>{const t=ui.world.map.get(id);return`<option value="${id}">(${t?.x},${t?.y})${id===v?.coreTileId?' 중심지':''}</option>`;}).join(''));if(!ids.includes(Number(ui.statsSettlementId)))ui.statsSettlementId=ids.includes(ui.world.selectedTileId)?ui.world.selectedTileId:ids[0];if(ui.statsSettlementId!=null)settle.value=String(ui.statsSettlementId);const opts=METRIC25[ui.statsScope]||METRIC25.nation;setOptions25(metric,ui.statsScope+Object.keys(opts).join(','),Object.entries(opts).map(([k,x])=>`<option value="${k}">${x[0]}</option>`).join(''));if(!opts[ui.statsMetric])ui.statsMetric='population';metric.value=ui.statsMetric;period.value=String(ui.statsPeriod||0);nation.style.display=ui.statsScope==='world'?'none':'';settle.style.display=ui.statsScope==='settlement'?'':'none';const note=ui.q('statsNote');if(note)note.textContent='V0.25: Hunger와 노동일/유지보수 데이터를 장기 로그에 함께 기록합니다.';
 const wrap=canvas.parentElement,W=Math.max(300,Math.min(920,wrap?.clientWidth||760)),H=350,dpr=Math.min(2,window.devicePixelRatio||1);canvas.width=Math.round(W*dpr);canvas.height=Math.round(H*dpr);canvas.style.width=W+'px';canvas.style.height=H+'px';const ctx=canvas.getContext('2d');ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,W,H);const rows=statsRows25(ui),label=(opts[ui.statsMetric]||['값'])[0],pad={l:58,r:18,t:24,b:38};ctx.font='12px system-ui';ctx.fillStyle='#93a6bf';if(!rows.length){ctx.fillText('이 조건에서 표시할 연간 기록이 없습니다.',24,45);return;}let min=Math.min(...rows.map(x=>x.value)),max=Math.max(...rows.map(x=>x.value));if(min===max){min=Math.max(0,min-1);max+=1;}const margin=(max-min)*.08||1;min=Math.max(0,min-margin);max+=margin;const x0=pad.l,cw=W-pad.l-pad.r,ch=H-pad.t-pad.b,xf=y=>rows.length===1?x0+cw/2:x0+(y-rows[0].year)/(rows.at(-1).year-rows[0].year||1)*cw,yf=x=>pad.t+(max-x)/(max-min)*ch;ctx.strokeStyle='#2a3d58';for(let i=0;i<=4;i++){const y=pad.t+ch*i/4,val=max-(max-min)*i/4;ctx.beginPath();ctx.moveTo(x0,y);ctx.lineTo(x0+cw,y);ctx.stroke();ctx.fillStyle='#93a6bf';ctx.textAlign='right';ctx.fillText(Math.abs(val)>=1000?Math.round(val).toLocaleString():val.toFixed(Math.abs(max-min)<10?2:1),x0-7,y+4);}ctx.strokeStyle='#69adff';ctx.lineWidth=2.5;ctx.beginPath();rows.forEach((r,i)=>{const x=xf(r.year),y=yf(r.value);i?ctx.lineTo(x,y):ctx.moveTo(x,y);});ctx.stroke();ctx.fillStyle='#eef5ff';ctx.textAlign='left';ctx.font='700 13px system-ui';ctx.fillText(label,pad.l,pad.t-7);ctx.font='11px system-ui';ctx.fillStyle='#93a6bf';ctx.textAlign='center';for(const i of [0,Math.floor((rows.length-1)/2),rows.length-1].filter((v,i,a)=>a.indexOf(v)===i))ctx.fillText(`${rows[i].year}년`,xf(rows[i].year),H-14);const last=rows.at(-1);ctx.fillStyle='#eef5ff';ctx.textAlign='right';ctx.fillText(`최근 ${last.year}년 · ${last.value.toLocaleString(undefined,{maximumFractionDigits:3})}`,W-pad.r,pad.t-7);}

if(NS.UI){const header24=NS.UI.prototype.renderHeader,renderStats24=NS.UI.prototype.renderStats,codex24=NS.UI.prototype.renderCodex,social24=NS.UI.prototype.renderVillageContent,settlementCard24=NS.UI.prototype.settlementCard;NS.UI.prototype.renderHeader=function(){header24.call(this);this.q('runtimeStatus').textContent='✓ V0.25 인구 사망구조 · Hunger 아사 · 노동일 건설 · 내구도/지역 유지보수 개편';document.title='Village Observer V0.26';const e=document.querySelector('.eyebrow');if(e)e.textContent='Village Observer · V0.26';};NS.UI.prototype.renderStats=function(){renderStats25(this);};NS.UI.prototype.renderCodex=function(){codex24.call(this);const el=this.q('codexContent');if(!el)return;const buildPage=el.querySelector('[data-page="build"]');for(const note of [...el.querySelectorAll('.codex-note')])if(note.textContent.includes('기본 건설기간'))note.remove();if(buildPage&&!buildPage.querySelector('.v25-labor-note')){const note=document.createElement('div');note.className='codex-note v25-labor-note';note.innerHTML='<strong>V0.25 노동일 건설·유지보수</strong><br>노동량 1 = 일반 성인 1명의 하루 전업 노동입니다. 건설은 고정 공사기간이 아니라 실제 투입된 Person의 노동일로 진행되며, 건설 담당자는 그 작업 사이클 동안 본업 생산을 포기합니다.<br>분기 유지보수 기본 노동량은 별도 유지보수 기준 노동량의 0.5%이며, D1B의 단축된 건설 노동량과 분리됩니다.';buildPage.insertAdjacentElement('afterbegin',note);}for(const row of el.querySelectorAll('.codex-row')){const strong=row.querySelector('strong'),left=row.children[0];if(!strong||!left)continue;const type=Object.keys(NS.BUILDINGS||{}).find(k=>strong.textContent.includes(NS.BUILDINGS[k]?.label));if(type&&TOTAL_LABOR25[type]!=null){let x=left.querySelector('.v15-build-time');if(!x){x=document.createElement('div');x.className='small v15-build-time';left.appendChild(x);}x.textContent=`👷 총 필요 노동량 ${TOTAL_LABOR25[type]} 노동일`;}}};NS.UI.prototype.settlementCard=function(v,id){let html=settlementCard24.call(this,v,id);const t=this.world.map.get(id),labor=(t?.buildings||[]).reduce((a,type)=>a+maintLaborNeed25(type),0);html=html.replace(/(분기 유지:[^<]*?노동 )([0-9.]+)/,`$1${labor.toFixed(2)} 노동일`);return html;};NS.UI.prototype.renderVillageContent=function(){social24.call(this);if(this.sub==='economy'){for(const x of this.q('villageContent')?.querySelectorAll('.v11-plan .small.muted')||[])x.textContent=x.textContent.replace(/· 기본 ([0-9.]+)일/g,'· 총 노동량 $1 노동일');}if(this.sub==='social'){const body=this.q('v24SocialBody');if(body){const v=this.world.selectedNation,scope=this.socialScope23||'nation',ps=scope==='world'?this.world.allPeople:scope.startsWith('s:')?v.residents.filter(p=>p.alive&&p.homeTileId===Number(scope.slice(2))):v.residents.filter(p=>p.alive),avg=ps.length?ps.reduce((a,p)=>a+Number(p.hunger||0),0)/ps.length:0;body.insertAdjacentHTML('afterbegin',`<div class="small muted" style="margin-bottom:8px">평균 Hunger <strong>${avg.toFixed(1)}</strong></div>`);}}};}

